// Doğrulanmış arşiv dergi görselleri. Cloudflare Worker t.me/widget isteği
// yapamadığı için bu üç görsel aynı kökenli /api/tg?magPhoto=publicmag_* ucundan
// bayt olarak sunulur; çalışma anında Telegram CDN'ine çıkılmaz.
export const LEGACY_MAGAZINE_PHOTOS = Object.freeze({
  "987": [
    ""
  ],
  "1195": [
    ""
  ],
  "1205": [
    ""
  ]
});

export function legacyMagazinePhoto(message, index) {
  const list = LEGACY_MAGAZINE_PHOTOS[String(Number(message))];
  const b64 = list && list[Number(index) || 0];
  if (!b64 || !/^[A-Za-z0-9+/]+={0,2}$/.test(b64)) return null;
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}
